// ——— Messenger event normalize (user message + page echo দুটোই) ———
const body = $input.first().json.body || $input.first().json;
const entry = body.entry?.[0];
const messaging = entry?.messaging?.[0];
const pageId = entry?.id || '';

if (!messaging || !messaging.message) {
  return [{ json: { skip: true } }];
}

const message = messaging.message;
const isEcho = message.is_echo === true;

// is_echo = পেজ থেকে পাঠানো মেসেজ (হয় AI পাঠিয়েছে, নয়তো সাইজুল নিজে)
// সাধারণ ইউজার মেসেজে sender = ইউজার, recipient = পেজ
// echo-তে sender = পেজ, recipient = ইউজার
let senderId, userId;
if (isEcho) {
  userId = messaging.recipient?.id || '';   // যাকে পাঠানো হয়েছে = কাস্টমার
  senderId = messaging.sender?.id || '';
} else {
  userId = messaging.sender?.id || '';      // যে পাঠিয়েছে = কাস্টমার
  senderId = userId;
}

const messageText = message.text || '';

// attachment হলে টেক্সট ফাঁকা থাকতে পারে
if (!messageText && !isEcho && !message.attachments) {
  return [{ json: { skip: true } }];
}

return [{
  json: {
    skip: false,
    isEcho,
    userId,            // সবসময় কাস্টমারের ID (state key)
    pageId,
    messageText,
    hasAttachment: !!message.attachments,
    timestamp: Date.now()
  }
}];

// ——— পেজ থেকে আসা echo handle করা ———
// AI নিজে পাঠালে = ignore। সাইজুল নিজে লিখলে = human mode চালু।
const ev = $('Normalize Event').first().json;
const stateRows = $('Get Conversation State').all().filter(r => r.json.user_id);
const row = stateRows[0]?.json || {};

const lastAiMsg = (row.last_ai_message || '').trim();
const echoText = (ev.messageText || '').trim();

// রিজিউম কমান্ড: সাইজুল চ্যাটে #ai লিখলে AI আবার চালু
if (echoText.toLowerCase() === '#ai') {
  return [{ json: { action: 'resume', userId: ev.userId, pageId: ev.pageId } }];
}

// echo টেক্সট সদ্য পাঠানো AI মেসেজের সাথে মিললে = AI-এর নিজের echo, কিছু করো না
if (echoText && echoText === lastAiMsg) {
  return [{ json: { action: 'ignore', userId: ev.userId } }];
}

// নাহলে এটা সাইজুলের ম্যানুয়াল রিপ্লাই → human mode চালু
return [{ json: { action: 'human_takeover', userId: ev.userId, pageId: ev.pageId, humanText: echoText } }];

// ——— ইউজার মেসেজ: human mode চেক ———
const ev = $('Normalize Event').first().json;
const stateRows = $('Get Conversation State').all().filter(r => r.json.user_id);
const row = stateRows[0]?.json || {};

let history = [];
try { history = JSON.parse(row.conversation_history || '[]'); } catch (e) {}

const humanMode = row.human_mode === 'true' || row.human_mode === true;
const lastHumanTime = row.last_human_time ? new Date(row.last_human_time).getTime() : 0;

// human mode অটো-রিজিউম: সাইজুল ৬ ঘণ্টা নিষ্ক্রিয় থাকলে AI আবার চালু
const SIX_HOURS = 6 * 60 * 60 * 1000;
const autoResume = humanMode && lastHumanTime && (Date.now() - lastHumanTime > SIX_HOURS);
const effectiveHumanMode = humanMode && !autoResume;

history.push({ role: 'user', content: ev.messageText || '[একটি ছবি/অ্যাটাচমেন্ট পাঠিয়েছে]' });
if (history.length > 24) history = history.slice(-24);

return [{
  json: {
    ...ev,
    conversationHistory: history,
    humanMode: effectiveHumanMode,
    isNew: stateRows.length === 0
  }
}];

