// AI আউটপুট parse + [HANDOVER] শনাক্ত
const aiOut = $input.first().json;
const raw = aiOut.content || aiOut.text || aiOut.message?.content || '';

let needsHandover = /\[HANDOVER\]/i.test(raw);
let clean = raw.replace(/\[HANDOVER\]/ig, '').trim();

const ctx = $('Build Context & Check Mode').first().json;
const history = [...(ctx.conversationHistory || [])];
history.push({ role: 'assistant', content: clean });

return [{ json: { ...ctx, aiResponse: clean, needsHandover, conversationHistory: history.slice(-24) } }];

